534	void lvgl_ui_channel_show(void)
535	{
536	    if (!s_state.initialized || !s_state.running) {
537	        syslog(LOG_ERR, "[%s] show: channel not ready\n", TAG);
538	        return;
539	    }
540	
541	    if (s_state.screen_visible) {
542	        return;
543	    }
544	
545	    /* Schedule screen load in LVGL thread to avoid cross-thread
546	     * invalidation assertion. */
547	    lv_async_call(show_screen_async_cb, NULL);
